61	        Set<String> createdClasses = new HashSet<>();
62	        toBeGenerated.addAll(classInfos);
63	
64	        while (!toBeGenerated.isEmpty()) {
65	            create(toBeGenerated.removeFirst()).ifPresent(createdClasses::add);
66	        }
67	
68	        return createdClasses;
69	    }
